def gen(rng):
    def build(n, mode, H, k=2):
        depth = [0]
        par = [-1]
        cand = [0]
        for i in range(1, n):
            if mode == 'star':
                p = 0
            elif mode == 'kary':
                p = (i - 1) // k
                if depth[p] >= H:
                    p = rng.choice(cand)
            elif mode == 'deep':
                if rng.random() < 0.1:
                    p = rng.choice(cand)
                else:
                    p = cand[-1 - rng.randint(0, min(2, len(cand) - 1))]
            else:
                p = rng.choice(cand)
            par.append(p)
            depth.append(depth[p] + 1)
            if depth[i] < H:
                cand.append(i)
        return par

    def fmt(n, par, nq, qmode='rand'):
        perm = list(range(1, n))
        rng.shuffle(perm)
        lab = [0] + perm
        edges = []
        for i in range(1, n):
            a, b = lab[par[i]], lab[i]
            if rng.random() < 0.5:
                a, b = b, a
            edges.append((a, b))
        rng.shuffle(edges)
        qs = []
        for _ in range(nq):
            if qmode == 'rand' or n == 1:
                qs.append((rng.randrange(n), rng.randrange(n)))
            else:
                x = rng.randrange(n)
                y = lab[par[rng.randrange(1, n)]] if rng.random() < 0.5 else rng.randrange(n)
                qs.append((x, y))
        lines = [str(n)] + [f'{a} {b}' for a, b in edges] + [str(nq)] + [f'{a} {b}' for a, b in qs]
        return '\n'.join(lines)

    tests = []
    tests.append('1\n3\n0 0\n0 0\n0 0')
    tests.append('2\n0 1\n3\n0 1\n1 1\n1 0')
    tests.append('5\n0 1\n1 2\n2 3\n3 4\n4\n4 2\n0 4\n3 3\n1 4')
    tests.append('5\n0 1\n0 2\n0 3\n0 4\n3\n1 2\n3 4\n0 4')
    for n in (3, 4, 6, 8, 10, 12):
        for mode in ('rand', 'deep', 'rand', 'star'):
            par = build(n, mode, 100)
            tests.append(fmt(n, par, 8, rng.choice(['rand', 'anc'])))
    tests.append(fmt(50000, build(50000, 'rand', 5000), 50000))
    tests.append(fmt(50000, build(50000, 'deep', 5000), 50000, 'anc'))
    tests.append(fmt(50000, build(50000, 'kary', 5000, 3), 50000))
    tests.append(fmt(50000, build(50000, 'star', 5000), 50000))
    return tests

